<script setup lang="ts">
import { computed, ref } from "vue"
import { useRouter } from "vue-router"
import { IconDownload, IconEye, IconPlus, IconRefresh, IconSearch } from "@tabler/icons-vue"
import { useMonitoramentoStore } from "../../stores/monitoramentoStore"
import type { MonitoramentoStatus } from "../../types/monitoramento"

const router = useRouter()
const store = useMonitoramentoStore()
const busca = ref("")
const situacao = ref<MonitoramentoStatus | "">("")
const ciclo = ref("")
const unidade = ref("")
const analista = ref("")
const carregando = ref(false)
const labels: Record<MonitoramentoStatus, string> = { RASCUNHO: "Rascunho", AGUARDANDO_ANALISE: "Aguardando análise", ACEITO: "Aceito", REJEITADO: "Rejeitado", AJUSTES_SOLICITADOS: "Ajustes solicitados" }
const isSecGov = computed(() => store.atorAtual.perfil === "SECGOV")
const unidades = computed(() => [...new Set(store.propostasVisiveis.map((item) => item.unidade))])
const analistas = computed(() => [...new Set(store.propostasVisiveis.map((item) => item.analista).filter(Boolean))])
const propostas = computed(() => { const termo = busca.value.trim().toLowerCase(); return store.propostasVisiveis.filter((item) => (!termo || `${item.nome} ${item.unidade} ${item.responsavel}`.toLowerCase().includes(termo)) && (!situacao.value || item.status === situacao.value) && (!ciclo.value || item.ciclo === ciclo.value) && (!unidade.value || item.unidade === unidade.value) && (!analista.value || item.analista === analista.value)) })
const indicadores = computed(() => [
    { status: "" as const, title: "Total de propostas", value: propostas.value.length, caption: "No recorte atual", color: "primary" },
    { status: "AGUARDANDO_ANALISE" as const, title: "Aguardando análise", value: propostas.value.filter((item) => item.status === "AGUARDANDO_ANALISE").length, caption: "Disponíveis para análise", color: "warning" },
    { status: "AJUSTES_SOLICITADOS" as const, title: "Ajustes solicitados", value: propostas.value.filter((item) => item.status === "AJUSTES_SOLICITADOS").length, caption: "Exigem complementação", color: "deep-purple" },
    { status: "ACEITO" as const, title: "Aceitas", value: propostas.value.filter((item) => item.status === "ACEITO").length, caption: "Decisão registrada", color: "success" },
    { status: "REJEITADO" as const, title: "Rejeitadas", value: propostas.value.filter((item) => item.status === "REJEITADO").length, caption: "Decisão registrada", color: "error" },
])
function limparFiltros() { busca.value = ""; situacao.value = ""; ciclo.value = ""; unidade.value = ""; analista.value = "" }
async function atualizar() { carregando.value = true; await new Promise((resolve) => setTimeout(resolve, 250)); carregando.value = false }
function exportar() { if (!store.atorAtual.podeExportar) return; const blob = new Blob(["\ufeff" + store.exportCsv(propostas.value)], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "monitoramento-processos.csv"; link.click(); URL.revokeObjectURL(url) }
</script>

<template>
    <VContainer fluid class="monitoramento-page">
        <div class="page-header"><div><h1>{{ isSecGov ? "Monitoramento" : "Monitoramento da Unidade" }}</h1><p>{{ isSecGov ? "Acompanhe e analise propostas das Unidades e da SecGov." : "Acompanhe as propostas da sua Unidade." }}</p></div><div class="header-actions"><VSelect v-model="store.atorAtualId" :items="store.atores" item-title="nome" item-value="id" label="Ator da demonstração" density="compact" hide-details class="actor-select" @update:model-value="store.setAtor" /><VBtn color="primary" @click="router.push({ name: 'MonitoramentoCadastro' })"><IconPlus size="18" /> Cadastrar proposta</VBtn><VBtn icon rounded density="comfortable" variant="outlined" aria-label="Atualizar" :loading="carregando" @click="atualizar"><IconRefresh size="18" /></VBtn><VBtn v-if="store.atorAtual.podeExportar" icon rounded density="comfortable" variant="outlined" aria-label="Exportar CSV" @click="exportar"><IconDownload size="18" /></VBtn></div></div>
        <div class="metrics-grid"><VCard v-for="item in indicadores" :key="item.title" class="metric-card"><VChip :color="item.color" size="small" variant="tonal">●</VChip><div><span>{{ item.title }}</span><strong>{{ item.value }}</strong><small>{{ item.caption }}</small></div></VCard></div>
        <VCard class="filters-card"><h3>Filtros e pesquisa</h3><div class="filters-grid"><VTextField v-model="busca" label="Nome, unidade ou responsável" placeholder="Buscar proposta" hide-details density="comfortable"><template #prepend-inner><IconSearch size="18" /></template></VTextField><VSelect v-model="ciclo" label="Ciclo / ano" :items="[...new Set(store.propostasVisiveis.map((item) => item.ciclo))]" clearable hide-details density="comfortable" /><VSelect v-model="unidade" label="Unidade" :items="unidades" clearable hide-details density="comfortable" /><VSelect v-model="analista" label="Analista" :items="analistas" clearable hide-details density="comfortable" /><VSelect v-model="situacao" label="Situação" :items="Object.entries(labels).map(([value, title]) => ({ value, title }))" clearable hide-details density="comfortable" /><VBtn color="primary" variant="outlined" @click="limparFiltros">Limpar filtros</VBtn></div></VCard>
        <VCard class="table-card"><div class="table-heading"><div><h3>Propostas monitoradas</h3><span>{{ propostas.length }} registros no recorte atual · ator: {{ store.atorAtual.nome }}</span></div></div><div class="table-scroll"><table><colgroup><col class="col-processo" /><col class="col-unidade" /><col class="col-ciclo" /><col class="col-situacao" /><col class="col-data" /><col class="col-responsavel" /><col class="col-acoes" /></colgroup><thead><tr><th>Processo / proposta</th><th>Unidade</th><th>Ciclo</th><th>Situação</th><th>Últ. atualização</th><th>Responsável</th><th>Ações</th></tr></thead><tbody><tr v-for="proposal in propostas" :key="proposal.id"><td><strong>{{ proposal.nome }}</strong><small>{{ proposal.subunidade || "Subunidade não informada" }}</small></td><td>{{ proposal.unidade }}</td><td>{{ proposal.ciclo }}</td><td><VChip size="small" :color="proposal.status === 'ACEITO' ? 'success' : proposal.status === 'REJEITADO' ? 'error' : proposal.status === 'AJUSTES_SOLICITADOS' ? 'deep-purple' : proposal.status === 'AGUARDANDO_ANALISE' ? 'warning' : 'grey'" variant="tonal">{{ labels[proposal.status] }}</VChip></td><td>{{ proposal.ultimaAtualizacao }}</td><td>{{ proposal.responsavel }}</td><td><VBtn icon variant="outlined" size="small" aria-label="Visualizar detalhes" @click="router.push({ name: 'MonitoramentoDetalhes', params: { id: proposal.id } })"><IconEye size="18" /></VBtn></td></tr><tr v-if="!propostas.length"><td colspan="7" class="empty-cell">Nenhuma proposta encontrada no escopo e filtros selecionados.</td></tr></tbody></table></div></VCard>
    </VContainer>
</template>

<style scoped>
.monitoramento-page{min-height:100%;padding:24px;background:#f5f7fb;box-sizing:border-box}.page-header{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:18px}.page-header h1{margin:0;color:#172033;font-size:28px;font-weight:400}.page-header p{margin:4px 0 0;color:#61708a}.header-actions{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;gap:10px}.actor-select{min-width:230px}.header-actions .v-btn:not(.v-btn--icon) svg{margin-right:6px}.metrics-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin:20px 0}.metric-card{display:flex;align-items:flex-start;gap:12px;padding:16px;border:1px solid #d8deea}.metric-card div{display:flex;flex-direction:column;gap:2px}.metric-card span,.metric-card small{color:#64748b;font-size:12px}.metric-card strong{color:#172033;font-size:26px}.filters-card,.table-card{display:block;width:100%;box-sizing:border-box;padding:18px;margin-bottom:16px;border:1px solid #d8deea}.filters-card h3,.table-card h3{display:block;width:100%;margin:0 0 14px;color:#1d293d;font-size:16px}.filters-grid{display:grid;grid-template-columns:minmax(240px,2fr) repeat(4,minmax(140px,1fr)) 150px;gap:12px;align-items:center}.table-heading{display:flex;width:100%;align-items:flex-start;justify-content:flex-start;gap:16px}.table-heading span{color:#64748b;font-size:12px}.table-scroll{overflow-x:auto}table{width:100%;min-width:980px;border-collapse:collapse;table-layout:fixed}.col-processo{width:39%}.col-unidade{width:13%}.col-ciclo{width:8%}.col-situacao{width:14%}.col-data{width:12%}.col-responsavel{width:9%}.col-acoes{width:5%}th,td{padding:14px 10px;border-bottom:1px solid #e2e8f0;text-align:left;vertical-align:middle;color:#273449;font-size:13px}th{color:#64748b;font-size:12px;font-weight:700}td strong,td small{display:block}td:first-child strong{overflow-wrap:anywhere}td small{margin-top:3px;color:#77839a;font-size:11px}td:last-child,th:last-child{text-align:center}.empty-cell{text-align:center;padding:42px;color:#64748b}@media(max-width:1100px){.header-actions{justify-content:flex-start}.metrics-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.filters-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.page-header{flex-direction:column}.header-actions{width:100%;align-items:stretch}.actor-select{width:100%}.filters-grid{grid-template-columns:1fr}.metrics-grid{grid-template-columns:1fr}}
</style>
